class Solution:
    def findMinDifference(self, timePoints: list[str]) -> int:
        minutes = sorted(int(t[:2]) * 60 + int(t[3:]) for t in timePoints)
        best = minutes[0] + 1440 - minutes[-1]
        for a, b in zip(minutes, minutes[1:]):
            best = min(best, b - a)
        return best
